('link','Student portal','portal','Open the university’s student login page.','','','published',0,'{"url":"https://portal.madukauniversity.edu.ng/login","category":"Student services","placement":"directory","instructions":"Sign in with your email, registration or matriculation number. Use the portal’s password recovery if needed."}'::jsonb),
('link','Results portal','results','Go to the results service linked by the university.','','','published',1,'{"url":"https://result.madukauniversity.edu.ng/","category":"Student services","placement":"directory","instructions":"Follow the login and results instructions on the official portal."}'::jsonb),
('link','E-learning','elearning','Open the university’s online learning platform.','','','published',2,'{"url":"https://elearn.madukauniversity.edu.ng/","category":"Learning","placement":"directory","instructions":"Use the access details and course instructions provided by the school or your lecturer."}'::jsonb),
('link','University library','library','Find the official library page and its resources.','','','published',3,'{"url":"https://madukauniversity.edu.ng/library","category":"Learning","placement":"directory","instructions":"Select “Visit Main Library Portal” on the university’s library page to continue to the library service."}'::jsonb),
('link','Freshers’ prospectus','prospectus','Read the official registration and packing requirements.','','','published',4,'{"url":"https://madukauniversity.edu.ng/prospectus","category":"Getting started","placement":"directory","instructions":"Check the documents, recommended materials and prohibited items before travelling."}'::jsonb),
